package com.gerenciadorrural.modules.herd.api;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import com.fasterxml.jackson.databind.annotation.JsonDeserialize; import com.gerenciadorrural.modules.herd.application.*; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd") public class HerdReproductionController {private final ManageHerdReproduction s;private final ReadHerdReproduction reads;public HerdReproductionController(ManageHerdReproduction s,ReadHerdReproduction reads){this.s=s;this.reads=reads;}@PostMapping("/animals/{motherId}/breedings")ResponseEntity<?> breed(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestBody BreedingRequest r){return ResponseEntity.status(HttpStatus.CREATED).cacheControl(CacheControl.noStore()).body(s.breed(c,motherId,new ManageHerdReproduction.Breeding(r.operationId(),r.expectedVersion(),r.serviceType(),r.serviceOn(),r.sireReference(),r.expectedCalvingOn(),r.notes())));}@PostMapping("/animals/{motherId}/calvings")ResponseEntity<?> calve(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestBody CalvingRequest r){return ResponseEntity.status(HttpStatus.CREATED).cacheControl(CacheControl.noStore()).body(s.calve(c,motherId,new ManageHerdReproduction.Calving(r.operationId(),r.expectedVersion(),r.pregnancyId(),r.expectedPregnancyVersion(),r.calvedOn(),r.calfId(),r.identification(),r.name(),r.sex(),r.birthDate())));}@PostMapping("/pregnancies/{id}/confirmation")ResponseEntity<?> confirm(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody TransitionRequest r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(s.confirm(c,id,new ManageHerdReproduction.Transition(r.operationId(),r.expectedVersion(),r.occurredOn())));}@PostMapping("/pregnancies/{id}/termination")ResponseEntity<?> terminate(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody TerminationRequest r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(s.terminate(c,id,new ManageHerdReproduction.Transition(r.operationId(),r.expectedVersion(),r.endedOn()),r.reason()));}@GetMapping("/pregnancies/{id}")ResponseEntity<PregnancyItem> pregnancy(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(PregnancyItem.from(reads.pregnancy(c,id)));}@GetMapping("/animals/{motherId}/pregnancies")ResponseEntity<PregnancyPage> pregnancies(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest r){only(r);var x=reads.pregnancies(c,motherId,page,size);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new PregnancyPage(x.items().stream().map(PregnancyItem::from).toList(),x.page(),x.size(),x.totalElements(),x.totalPages()));}@GetMapping("/animals/{motherId}/calves")ResponseEntity<List<HerdAnimalController.Item>> calves(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest r){only(r);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(reads.calves(c,motherId,page,size).stream().map(HerdAnimalController.Item::from).toList());}@GetMapping("/animals/{calfId}/mother")ResponseEntity<HerdAnimalController.Item> mother(@ResolvedTenantContext TenantContext c,@PathVariable UUID calfId){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(HerdAnimalController.Item.from(reads.mother(c,calfId)));}private static void only(HttpServletRequest r){if(!Set.of("page","size").containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw new HerdAnimalQueryException();}public record PregnancyItem(UUID id,UUID motherId,ReproductionServiceType serviceType,LocalDate serviceOn,String sireReference,LocalDate expectedCalvingOn,PregnancyStatus status,LocalDate confirmedOn,LocalDate endedOn,PregnancyTerminationReason terminationReason,UUID calfAnimalId,long version){static PregnancyItem from(HerdReproductionRepository.Pregnancy x){return new PregnancyItem(x.id(),x.motherAnimalId(),x.serviceType(),x.serviceOn(),x.sireReference(),x.expectedCalvingOn(),x.status(),x.confirmedOn(),x.endedOn(),x.terminationReason(),x.calfAnimalId(),x.version());}}public record PregnancyPage(List<PregnancyItem> items,int page,int size,long totalElements,int totalPages){}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=ReproductionRequestDeserializers.Breeding.class)public record BreedingRequest(UUID operationId,long expectedVersion,ReproductionServiceType serviceType,LocalDate serviceOn,String sireReference,LocalDate expectedCalvingOn,String notes){}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=ReproductionRequestDeserializers.Calving.class)public record CalvingRequest(UUID operationId,long expectedVersion,UUID pregnancyId,Long expectedPregnancyVersion,LocalDate calvedOn,UUID calfId,String identification,String name,HerdAnimalSex sex,LocalDate birthDate){}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=ReproductionRequestDeserializers.Confirmation.class)public record TransitionRequest(UUID operationId,long expectedVersion,LocalDate occurredOn){}@JsonIgnoreProperties(ignoreUnknown=false)@JsonDeserialize(using=ReproductionRequestDeserializers.Termination.class)public record TerminationRequest(UUID operationId,long expectedVersion,LocalDate endedOn,PregnancyTerminationReason reason){}}
